/* Shashka Game - Main Application JS */

'use strict';

/* ===== API Helper ===== */
class Api {
  constructor() {
    this.base = '/api';
    this.token = localStorage.getItem('shashka_token') || null;
  }

  setToken(token) {
    this.token = token;
    localStorage.setItem('shashka_token', token);
  }

  async request(method, path, body) {
    const headers = { 'Content-Type': 'application/json' };
    if (this.token) headers['Authorization'] = 'Bearer ' + this.token;

    const opts = { method, headers };
    if (body) opts.body = JSON.stringify(body);

    try {
      const res = await fetch(this.base + path, opts);
      const data = await res.json();
      if (!res.ok || data.success === false) {
        throw new Error(data.error || 'Xatolik yuz berdi');
      }
      return data.data !== undefined ? data.data : data;
    } catch (err) {
      throw err;
    }
  }

  get(path) { return this.request('GET', path); }
  post(path, body) { return this.request('POST', path, body); }
  put(path, body) { return this.request('PUT', path, body); }
  del(path) { return this.request('DELETE', path); }
}

/* ===== Main App ===== */
class ShashkaApp {
  constructor() {
    this.api = new Api();
    this.tg = window.Telegram ? window.Telegram.WebApp : null;
    this.user = null;
    this.currentPage = 'home';
    this.ws = null;
    this.sound = new SoundManager();
  }

  async init() {
    this.initTelegram();
    this.initTheme();
    this.bindNavigation();
    this.bindOfflineDetection();

    try {
      await this.authenticate();
    } catch (e) {
      this.toast('Avtorizatsiya xatosi', 'error');
    }

    this.hideLoading();
    this.lazyLoadImages();
  }

  /* ----- Telegram WebApp ----- */
  initTelegram() {
    if (this.tg) {
      this.tg.ready();
      this.tg.expand();
      this.tg.enableClosingConfirmation();
    }
  }

  async authenticate() {
    const initData = this.tg ? this.tg.initData : '';
    if (!initData) {
      // Dev fallback - skip auth
      return;
    }
    const res = await this.api.post('/auth/telegram', { init_data: initData });
    if (res.token) {
      this.api.setToken(res.token);
      this.user = res.user;
      this.renderUserHeader();
    }
  }

  renderUserHeader() {
    if (!this.user) return;
    const dEl = document.getElementById('balanceDiamonds');
    const cEl = document.getElementById('balanceCoins');
    if (dEl) dEl.textContent = this.formatNumber(this.user.diamonds || 0);
    if (cEl) cEl.textContent = this.formatNumber(this.user.coins || 0);

    const nameEl = document.getElementById('userName');
    if (nameEl) nameEl.textContent = this.user.display_name || 'Mehmon';
    const ratingEl = document.getElementById('userRating');
    if (ratingEl) ratingEl.textContent = this.user.rating || 1000;
  }

  /* ----- Theme ----- */
  initTheme() {
    const saved = localStorage.getItem('shashka_theme');
    let theme = saved;
    if (!theme) {
      theme = (this.tg && this.tg.colorScheme) ? this.tg.colorScheme : 'light';
    }
    document.documentElement.setAttribute('data-theme', theme);
  }

  toggleTheme() {
    const current = document.documentElement.getAttribute('data-theme');
    const next = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('shashka_theme', next);
  }

  /* ----- Navigation (SPA) ----- */
  bindNavigation() {
    document.querySelectorAll('[data-page]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.preventDefault();
        this.navigate(el.getAttribute('data-page'));
      });
    });
  }

  navigate(page) {
    this.currentPage = page;

    document.querySelectorAll('.page').forEach((p) => p.classList.remove('active'));
    const target = document.getElementById('page-' + page);
    if (target) target.classList.add('active');

    document.querySelectorAll('.nav-item').forEach((n) => {
      n.classList.toggle('active', n.getAttribute('data-page') === page);
    });

    this.sound.play('tap');
    if (typeof this.onPageLoad === 'function') this.onPageLoad(page);
  }

  /* ----- Offline detection ----- */
  bindOfflineDetection() {
    window.addEventListener('offline', () => this.toast('Internet uzildi', 'error'));
    window.addEventListener('online', () => {
      this.toast('Internet tiklandi', 'success');
      if (this.ws) this.connectWebSocket();
    });
  }

  /* ----- WebSocket ----- */
  connectWebSocket() {
    if (!this.api.token) return;
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    try {
      this.ws = new WebSocket(proto + '://' + location.host + '/ws/');
      this.ws.onopen = () => {
        this.ws.send(JSON.stringify({ type: 'auth', token: this.api.token }));
      };
      this.ws.onmessage = (ev) => this.handleWsMessage(JSON.parse(ev.data));
      this.ws.onclose = () => {
        // Reconnect after 3s
        setTimeout(() => this.connectWebSocket(), 3000);
      };
    } catch (e) {
      // WebSocket not available
    }
  }

  handleWsMessage(msg) {
    if (msg.type === 'game_move_broadcast' && window.Game) {
      window.Game.onOpponentMove(msg);
    } else if (msg.type === 'notification') {
      this.toast(msg.message, 'info');
    }
  }

  wsSend(data) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(data));
    }
  }

  /* ----- Toast notifications ----- */
  toast(message, type) {
    type = type || 'info';
    let container = document.querySelector('.toast-container');
    if (!container) {
      container = document.createElement('div');
      container.className = 'toast-container';
      document.body.appendChild(container);
    }
    const el = document.createElement('div');
    el.className = 'toast ' + type;
    const icons = { success: '✅', error: '❌', info: 'ℹ️' };
    el.innerHTML = '<span>' + (icons[type] || '') + '</span><span>' + message + '</span>';
    container.appendChild(el);
    setTimeout(() => {
      el.style.opacity = '0';
      setTimeout(() => el.remove(), 300);
    }, 3000);
  }

  /* ----- Modal ----- */
  showModal(html) {
    let overlay = document.querySelector('.modal-overlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      overlay.innerHTML = '<div class="modal"><div class="modal-handle"></div><div class="modal-body"></div></div>';
      document.body.appendChild(overlay);
      overlay.addEventListener('click', (e) => {
        if (e.target === overlay) this.hideModal();
      });
    }
    overlay.querySelector('.modal-body').innerHTML = html;
    requestAnimationFrame(() => overlay.classList.add('show'));
  }

  hideModal() {
    const overlay = document.querySelector('.modal-overlay');
    if (overlay) overlay.classList.remove('show');
  }

  /* ----- Loading screen ----- */
  hideLoading() {
    const ls = document.querySelector('.loading-screen');
    if (ls) {
      ls.classList.add('hide');
      setTimeout(() => ls.remove(), 400);
    }
  }

  /* ----- Lazy load images ----- */
  lazyLoadImages() {
    const imgs = document.querySelectorAll('img[data-src]');
    if ('IntersectionObserver' in window) {
      const obs = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const img = entry.target;
            img.src = img.getAttribute('data-src');
            img.removeAttribute('data-src');
            obs.unobserve(img);
          }
        });
      });
      imgs.forEach((img) => obs.observe(img));
    } else {
      imgs.forEach((img) => { img.src = img.getAttribute('data-src'); });
    }
  }

  /* ----- Helpers ----- */
  formatNumber(n) {
    n = Number(n) || 0;
    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
    return String(n);
  }

  timeAgo(datetime) {
    const diff = Math.floor((Date.now() - new Date(datetime).getTime()) / 1000);
    if (diff < 60) return 'Hozirgina';
    if (diff < 3600) return Math.floor(diff / 60) + ' daqiqa oldin';
    if (diff < 86400) return Math.floor(diff / 3600) + ' soat oldin';
    return Math.floor(diff / 86400) + ' kun oldin';
  }
}

/* ===== Sound Manager (Web Audio API) ===== */
class SoundManager {
  constructor() {
    this.enabled = localStorage.getItem('shashka_sound') !== '0';
    this.ctx = null;
  }

  ensureCtx() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (AC) this.ctx = new AC();
    }
  }

  play(type) {
    if (!this.enabled) return;
    this.ensureCtx();
    if (!this.ctx) return;

    const freqs = { tap: 440, move: 330, capture: 220, win: 660, lose: 180 };
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.frequency.value = freqs[type] || 440;
    osc.type = 'sine';
    gain.gain.setValueAtTime(0.1, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.2);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.2);
  }

  toggle() {
    this.enabled = !this.enabled;
    localStorage.setItem('shashka_sound', this.enabled ? '1' : '0');
  }
}

/* ===== Bootstrap ===== */
window.App = new ShashkaApp();
document.addEventListener('DOMContentLoaded', () => window.App.init());
